class Solution { fun maxPerformance(n:Int,speed:IntArray,efficiency:IntArray,k:Int):Int{val order=(0 until n).sortedByDescending{efficiency[it]};val heap=java.util.PriorityQueue<Int>();var sum=0L;var answer=0L;for(index in order){heap.add(speed[index]);sum+=speed[index];if(heap.size>k)sum-=heap.remove();answer=maxOf(answer,sum*efficiency[index])};return (answer%1_000_000_007L).toInt()} }
